const descriptions={Casamento:'Da emoção do sim à alegria da festa. Um dia para viver perto de quem importa.','Festa infantil':'A alegria de ver os pequenos crescendo, cercados de cor, carinho e boas lembranças.','15 anos':'Uma nova fase merece uma festa com a sua personalidade. Conte para nós como você imagina esse dia.','Confraternização':'Reunir a equipe, brindar as conquistas e aproveitar a companhia. Vamos planejar esse encontro?'};document.querySelectorAll('.event').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.event').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});b.classList.add('active');b.setAttribute('aria-pressed','true');document.querySelector('#type').value=b.dataset.event;document.querySelector('#event-description').textContent=descriptions[b.dataset.event];const im=document.querySelector('#event-image');im.src='assets/'+b.dataset.img+'.webp';im.alt='Registro de evento na Green House';}));const dialog=document.querySelector('#lightbox');document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{const im=document.querySelector('#large-photo');im.src='assets/'+b.dataset.photo+'.webp';im.alt=b.querySelector('img').alt;dialog.showModal()}));document.querySelector('#close-photo').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});const date=document.querySelector('#date');const today=new Date();date.min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');document.querySelector('#event-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const text=`Olá, Green House! Meu nome é ${f.get('name')}. Gostaria de um orçamento.\n\nEvento: ${f.get('type')}\nData desejada: ${String(f.get('date')).split('-').reverse().join('/')}\nConvidados: ${f.get('guests')}\n${f.get('message')?'Detalhes: '+f.get('message'):''}\n\nPodem me informar a disponibilidade e as opções?`;window.open('https://wa.me/5598981698672?text='+encodeURIComponent(text),'_blank','noopener,noreferrer')});if('IntersectionObserver' in window){const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('h2,.intro p,.intro-image,.section-top p,.event,.event-layout figure,.photos button,.contact-copy p,form,details').forEach((el,i)=>{el.style.animationDelay=(i%3)*70+'ms';observer.observe(el)})}
